<template>
  <view class="jd-tabbar">
    <view
      v-for="tab in tabs"
      :key="tab.key"
      class="tab"
      :class="{ on: tab.key === active }"
      @tap="switchTo(tab)"
    >
      <jd-icon :name="tab.icon" :size="24" :color="tab.key === active ? '#C2410C' : '#7A6E63'" />
      <text class="label">{{ tab.label }}</text>
      <view v-if="tab.key === 'board' && badge" class="dot" />
    </view>
  </view>
</template>

<script setup>
import JdIcon from './JdIcon.vue'
import { TABS } from '@/store/session'

defineProps({
  active: { type: String, default: 'home' },
  badge: { type: Boolean, default: false }
})

const tabs = TABS

function switchTo(tab) {
  uni.reLaunch({ url: tab.path })
}
</script>

